//---------------------------------------------------------------------
//   SIMULATION FLOW
//---------------------------------------------------------------------
initial begin
    rst_n = 1'b1;
    in_mode_valid = 1'b0;
    in_mode = 2'd0;
    in_valid = 1'b0;
    in_bank = 2'd0;
    in_src_row = 6'd0;
    in_dst_row = 6'd0;
    in_data = 64'd0;
    total_latency = 0;
    check_en = 1'b0;
    
    reset_task();
    
    check_en = 1'b1;
    
    repeat(3) @(negedge clk);

    for (pat = 0; pat < pat_num; pat = pat + 1) begin
        delay_cycles = $urandom_range(2, 4);
        repeat(delay_cycles) @(negedge clk);
        
        generate_input_task();
        wait_out_valid_task();
        check_ans_task(); 

        $display("\033[1;32m[PASS] Pattern %03d / %03d passed! (Mode: %d) | Latency: %5d cycles \033[0m", pat + 1, pat_num, current_mode, latency);
    end
    
    YOU_PASS_task();
end

//---------------------------------------------------------------------
//   BACKGROUND CHECKS (AXI-1 ~ AXI-6, MAIN-3)
//---------------------------------------------------------------------
always @(negedge clk) begin
    if (rst_n === 1'b0) begin
        aw_valid_d = 1'b0; w_valid_d  = 1'b0; b_valid_d  = 1'b0; ar_valid_d = 1'b0; r_valid_d  = 1'b0;
        aw_ready_d = 1'b0; w_ready_d  = 1'b0; b_ready_d  = 1'b0; ar_ready_d = 1'b0; r_ready_d  = 1'b0;
        aw_addr_d  = 32'b0; w_data_d   = 64'b0; b_resp_d   = 2'b0; ar_addr_d  = 32'b0; r_data_d   = 64'b0; r_resp_d   = 2'b0;
        
