        w_delay_cnt = 0; b_delay_cnt = 0; r_delay_cnt = 0;
    end 
    else if (check_en === 1'b1) begin
        
        // [SPEC MAIN-3 Background Check]
        if (out_valid === 1'b0 && out_data !== 64'b0) begin
            $display("\n[ERROR MAIN-3] out_data must be 0 when out_valid is 0! (out_data = %h)", out_data);
            fail_MAIN_3();
        end

        // [SPEC AXI-1]
        if (aw_valid !== 1'b1 && aw_addr !== 32'b0) begin
            $display("\n[ERROR AXI-1] AW channel: addr should be 0 when valid is 0. (aw_addr=%h)", aw_addr);
            fail_AXI_1();
        end
        if (w_valid !== 1'b1 && w_data !== 64'b0) begin 
            $display("\n[ERROR AXI-1] W channel: data should be 0 when valid is 0. (w_data=%h)", w_data);
