        end
        if (ar_valid !== 1'b1 && ar_addr !== 32'b0) begin 
            $display("\n[ERROR AXI-1] AR channel: addr should be 0 when valid is 0. (ar_addr=%h)", ar_addr);
            fail_AXI_1();
        end
        if (r_valid !== 1'b1 && (r_data !== 64'b0 || r_resp !== 2'b0)) begin
            $display("\n[ERROR AXI-1] R channel: data and resp should be 0 when valid is 0. (r_data=%h, r_resp=%b)", r_data, r_resp);
