            w_unmatched_count = w_unmatched_count + 1; 
        end 
        else if (b_valid === 1'b1 && b_ready === 1'b1) begin
            w_unmatched_count = w_unmatched_count - 1; 
        end

        if (ar_valid === 1'b1 && ar_ready === 1'b1 && r_valid === 1'b1 && r_ready === 1'b1) begin
            ar_unmatched_count = ar_unmatched_count; 
        end 
        else if (ar_valid === 1'b1 && ar_ready === 1'b1) begin
            ar_unmatched_count = ar_unmatched_count + 1; 
        end 
        else if (r_valid === 1'b1 && r_ready === 1'b1) begin
            ar_unmatched_count = ar_unmatched_count - 1; 
        end

        if (aw_valid === 1'b1 && aw_ready !== 1'b1) begin
            aw_wait_cnt = aw_wait_cnt + 1;
            if (aw_wait_cnt >= 50) begin
                $display("\n[ERROR AXI-5] AW channel ready timeout! (> 100 cycles)");
                fail_AXI_5();
            end 
        end 
        else aw_wait_cnt = 0;

        if (w_valid === 1'b1 && w_ready !== 1'b1) begin
            w_wait_cnt = w_wait_cnt + 1;
            if (w_wait_cnt > 100) begin
                $display("\n[ERROR AXI-5] W channel ready timeout! (> 100 cycles)");
                fail_AXI_5();
            end 
        end 
        else w_wait_cnt = 0;

        if (b_valid === 1'b1 && b_ready !== 1'b1) begin
            b_wait_cnt = b_wait_cnt + 1;
            if (b_wait_cnt > 100) begin
                $display("\n[ERROR AXI-5] B channel ready timeout! (> 100 cycles)");
                fail_AXI_5();
            end 
        end 
        else b_wait_cnt = 0;

        if (ar_valid === 1'b1 && ar_ready !== 1'b1) begin
            ar_wait_cnt = ar_wait_cnt + 1;
            if (ar_wait_cnt > 50) begin
                $display("\n[ERROR AXI-5] AR channel ready timeout! (> 100 cycles)");
                fail_AXI_5();
            end 
        end 
        else ar_wait_cnt = 0;

        if (r_valid === 1'b1 && r_ready !== 1'b1) begin
            r_wait_cnt = r_wait_cnt + 1;
            if (r_wait_cnt > 100) begin 
                $display("\n[ERROR AXI-5] R channel ready timeout! (> 100 cycles)");
                fail_AXI_5();
            end 
        end 
        else r_wait_cnt = 0;

        // [SPEC AXI-6: Valid Timeout Check]
        if (aw_unmatched_count > 0 && w_valid !== 1'b1) begin
            w_delay_cnt = w_delay_cnt + 1;
            if (w_delay_cnt > 150) begin
                $display("\n[ERROR AXI-6] W channel valid timeout! Wait AW handshake done > 150 cycles");
                fail_AXI_6();
            end
        end 
        else w_delay_cnt = 0;

        if (w_unmatched_count > 0 && b_valid !== 1'b1) begin
            b_delay_cnt = b_delay_cnt + 1;
            if (b_delay_cnt > 150) begin
                $display("\n[ERROR AXI-6] B channel valid timeout! Wait W handshake done > 150 cycles");
                fail_AXI_6();
            end
        end 
        else b_delay_cnt = 0;

        if (ar_unmatched_count > 0 && r_valid !== 1'b1) begin
            r_delay_cnt = r_delay_cnt + 1;
            if (r_delay_cnt > 150) begin
                $display("\n[ERROR AXI-6] R channel valid timeout! Wait AR handshake done > 150 cycles");
                fail_AXI_6();
            end
        end 
        else r_delay_cnt = 0;

        // [AXI-2 History Update]
        aw_valid_d = aw_valid; aw_addr_d  = aw_addr; aw_ready_d = aw_ready;
        w_valid_d  = w_valid;  w_data_d   = w_data;  w_ready_d  = w_ready;
        b_valid_d  = b_valid;  b_resp_d   = b_resp;  b_ready_d  = b_ready;
        ar_valid_d = ar_valid; ar_addr_d  = ar_addr; ar_ready_d = ar_ready;
        r_valid_d  = r_valid;  r_data_d   = r_data;  r_resp_d   = r_resp; r_ready_d  = r_ready;
    end
end

//=======================================================================
// SPEC MAIN-1
//=======================================================================
task reset_task; begin
    force clk = 0;
    rst_n = 1'b1;
    #(CYCLE);
    rst_n = 1'b0;
    #(CYCLE*3);

    if (out_valid !== 1'b0 || out_data !== 64'b0 ||
        aw_addr !== 32'b0 || aw_valid !== 1'b0 || aw_ready !== 1'b0 ||
        w_data !== 64'b0 || w_valid !== 1'b0 || w_ready !== 1'b0 || b_resp !== 2'b0 || 
        b_valid !== 0 || b_ready !== 1'b0 || ar_ready !== 1'b0 || r_data !== 64'b0 || r_resp !== 2'b0 ||
        ar_addr !== 32'b0 || ar_valid !== 1'b0 || r_ready !== 1'b0 || r_valid !== 1'b0) begin
        
        $display("\n[ERROR MAIN-1] Output signals should be reset!");
        $display("out_valid: %b, out_data: %h", out_valid, out_data);
        $display("AW: valid=%b, ready=%b, addr=%h", aw_valid, aw_ready, aw_addr);
        $display("W:  valid=%b, ready=%b, data=%h", w_valid, w_ready, w_data);
        $display("B:  valid=%b, ready=%b, resp=%h", b_valid, b_ready, b_resp);
        $display("AR: valid=%b, ready=%b, addr=%h", ar_valid, ar_ready, ar_addr);
        $display("R:  valid=%b, ready=%b, data=%h, resp=%h", r_valid, r_ready, r_data, r_resp);
        fail_MAIN_1(); 
    end

    #(CYCLE);
    rst_n = 1'b1;
    release clk;
end endtask

task automatic eval_tree_task;
    input  [15:0] ptr;
    output signed [63:0] result; 
    
    reg [63:0] node;
    reg [1:0] opcode;
    reg signed [63:0] left_val, right_val;
    reg signed [30:0] val_31;
    begin
        node = golden_DRAM[ptr];
        
        if (node[63] == 1'b0) begin
            val_31 = node[62:32];
            result = val_31; 
        end 
        else begin
            opcode = node[33:32];
            
            eval_tree_task(node[31:16], left_val);
            eval_tree_task(node[15:0], right_val);
            
            case (opcode)
                2'b00: result = left_val + right_val;
                2'b01: result = left_val - right_val;
                2'b10: result = left_val * right_val;
                2'b11: result = left_val >>> right_val[5:0];
            endcase
        end
    end
endtask

task generate_input_task; begin
    mode_rand = $urandom_range(0, 7);
    current_mode = (mode_rand == 0) ? 2'd0 : 
                   (mode_rand == 1) ? 2'd1 : 
                   (mode_rand <= 4) ? 2'd2 : 2'd3;
    // current_mode = 1;
    in_mode = current_mode;
    in_mode_valid = 1'b1;
    @(negedge clk);
    
    in_mode_valid = 1'b0;
    in_mode = 2'd0; 

    saved_bank    = $urandom_range(0, 3);      
    saved_src_row = (current_mode == 2'd2) ? $urandom_range(0, 31) : $urandom_range(0, 62);   
    saved_dst_row = $urandom_range(32, 62);  
    
    in_bank    = saved_bank;
    in_src_row = saved_src_row;
    in_dst_row = saved_dst_row;
    in_data    = 64'd0; 

    if (current_mode == 2'd0) begin 
        // --- READ Mode ---
        in_valid = 1'b1; 
        expected_cycles = 256;
        @(negedge clk);
        in_valid = 1'b0;
        
        for (i = 0; i < 256; i = i + 1) begin
            golden_ans_queue[i] = golden_DRAM[{saved_bank, saved_src_row, i[7:0]}];
        end
    end 
    else if (current_mode == 2'd1) begin 
        // --- WRITE Mode ---
        in_valid = 1'b1; 
        expected_cycles = 1;
        for (i = 0; i < 256; i = i + 1) begin
            in_data = {$urandom, $urandom};
            golden_DRAM[{saved_bank, saved_dst_row, i[7:0]}] = in_data;
            @(negedge clk);
        end
        in_valid = 1'b0;
        in_data = 64'd0;
    end 
    else if (current_mode == 2'd2) begin 
        // --- CALC Mode ---
        in_valid = 1'b1; 
        expected_cycles = 4;
        @(negedge clk);
        in_valid = 1'b0;
        
        for (i = 0; i < 4; i = i + 1) begin
            eval_tree_task({i[1:0], saved_src_row, 8'd0}, golden_ans_queue[i]);
        end
    end 
    else if (current_mode == 2'd3) begin 
        // --- SORT Mode ---
        in_valid = 1'b1; 
        expected_cycles = 1;
        @(negedge clk);
        in_valid = 1'b0;
        
        for (i = 0; i < 1024; i = i + 1) begin
            sort_data[i] = {i[9:8], saved_src_row[5:0], i[7:0], golden_DRAM[{i[9:8], saved_src_row, i[7:0]}]};
        end
        
        for (s_i = 0; s_i < 1024; s_i = s_i + 1) begin
            for (s_j = 0; s_j < 1023 - s_i; s_j = s_j + 1) begin
                val_A  = sort_data[s_j][62:32];
                val_B  = sort_data[s_j+1][62:32];
                addr_A = sort_data[s_j][79:64];
                addr_B = sort_data[s_j+1][79:64];

                if ( (val_A > val_B) || ((val_A == val_B) && (addr_A > addr_B)) ) begin
                    temp_data        = sort_data[s_j];
                    sort_data[s_j]   = sort_data[s_j+1];
                    sort_data[s_j+1] = temp_data;
                end 
            end
        end
        
        for (i = 0; i < 1024; i = i + 1) begin
            golden_DRAM[{i[9:8], saved_dst_row, i[7:0]}] = sort_data[i][63:0];
        end
    end
    
    in_bank    = 2'd0;
    in_src_row = 6'd0;
    in_dst_row = 6'd0;
end endtask

task wait_out_valid_task; begin
    latency = 0;
    while (out_valid === 1'b0) begin
        latency = latency + 1;
        if (latency > 10000) begin
            $display("\n[ERROR MAIN-2] exceeded 10000 cycles!");
            fail_MAIN_2();
        end 
        @(negedge clk);
    end
    total_latency = total_latency + latency;
end endtask

task check_ans_task; begin
    flag_main4_fail = 0;
    flag_main5_fail = 0;

    for (ans_idx = 0; ans_idx < expected_cycles; ans_idx = ans_idx + 1) begin
        if (out_valid !== 1'b1) begin
            $display("\n[ERROR MAIN-3] out_valid should be HIGH at expected cycle %0d", ans_idx);
            fail_MAIN_3();
        end
        
        if (current_mode == 2'd0 || current_mode == 2'd2) begin
            if (out_data !== golden_ans_queue[ans_idx]) begin 
                flag_main4_fail = 1; 
                $display("\n[ERROR MAIN-4] Mode %d: Expected %h, Got %h at cycle %0d", current_mode, golden_ans_queue[ans_idx], out_data, ans_idx);
            end
        end 
        else begin
            if (out_data !== 64'b0) begin
                flag_main4_fail = 1;
                $display("\n[ERROR MAIN-4] Mode %d: Expected out_data to be 0, Got %h", current_mode, out_data);
            end
        end
        
        if (current_mode == 2'd1 || current_mode == 2'd3) begin
            check_dram_task();
        end

        @(negedge clk);
    end
    
    if (out_valid !== 1'b0) begin
        $display("\n[ERROR MAIN-3] out_valid should pull LOW immediately after completing the specific cycles!");
        fail_MAIN_3();
    end 
    
    if (flag_main4_fail) fail_MAIN_4();
    if (flag_main5_fail) fail_MAIN_5();

end endtask

task check_dram_task; begin
    if (current_mode == 2'd1) begin
        for (i = 0; i < 256; i = i + 1) begin
            if (golden_DRAM[{saved_bank, saved_dst_row, i[7:0]}] !== u_DRAM.DRAM[{saved_bank, saved_dst_row, i[7:0]}]) begin
                flag_main5_fail = 1;
                $display("\n[ERROR MAIN-5] WRITE Mode Mismatch at B%0d_R%0d_C%0d! \n-> Expected: %h \n-> RTL DRAM: %h", 
                          saved_bank, saved_dst_row, i[7:0], golden_DRAM[{saved_bank, saved_dst_row, i[7:0]}], u_DRAM.DRAM[{saved_bank, saved_dst_row, i[7:0]}]);
            end
        end
    end else if (current_mode == 2'd3) begin
        for (b = 0; b < 4; b = b + 1) begin
            for (i = 0; i < 256; i = i + 1) begin
                if (golden_DRAM[{b[1:0], saved_dst_row, i[7:0]}] !== u_DRAM.DRAM[{b[1:0], saved_dst_row, i[7:0]}]) begin
                    flag_main5_fail = 1;
                    $display("\n[ERROR MAIN-5] SORT Mode Mismatch at B%0d_R%0d_C%0d! \n-> Expected: %h \n-> RTL DRAM: %h", 
                              b[1:0], saved_dst_row, i[7:0], golden_DRAM[{b[1:0], saved_dst_row, i[7:0]}], u_DRAM.DRAM[{b[1:0], saved_dst_row, i[7:0]}]);
                end
            end
        end
    end
end endtask

endmodule

